tool_call.arguments:
{"summary": "Retry WS handshake and HTTP probe of hocuspocus", "command": "cd /tmp && cat > wstest.sh <<'EOF'
#!/bin/bash
exec 3<>/dev/tcp/127.0.0.1/1234 || { echo "CONNECT FAIL"; exit 1; }
printf 'GET /board/ HTTP/1.1\r\nHost: localhost:1234\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n' >&3
sleep 2
head -c 400 <&3
exec 3>&- 3<&-
EOF
chmod +x wstest.sh && ./wstest.sh; echo; echo "=== HTTP probe ==="; curl -sS -o /dev/null -w 'HTTP %{http_code}\n' --max-time 5 http://localhost:1234/ ; curl -sS --max-time 5 http://localhost:1234/ | head -c 200; echo", "security_risk": "LOW"}
